using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ShopItem", menuName = "Data/Shop/ShopItem", order = 0)]
public class ShopItem : ScriptableObject
{
	[Header("Info")]
	[SerializeField]
	private Reward reward;

	[SerializeField]
	protected int cost;

	[SerializeField]
	private bool oneUseOnly;

	[Header("Meissa and Saiph Gift")]
	[SerializeField]
	private bool meissaGift;

	[SerializeField]
	private bool saiphGift;

	public Reward Reward => reward;

	public int RawCost => cost;

	public bool OneUseOnly => oneUseOnly;

	private bool meissaOrSaiphGift
	{
		get
		{
			if (!meissaGift)
			{
				return saiphGift;
			}
			return true;
		}
	}

	public virtual int GetCost()
	{
		return GetCostWithDiscountsAndPriceIncreaseCheck(GetCostWithModifications());
	}

	protected virtual int GetCostWithModifications()
	{
		return cost;
	}

	protected int GetCostWithDiscountsAndPriceIncreaseCheck(int cost)
	{
		if (meissaGift)
		{
			cost = ReferenceSingleton<RunModifiersManager>.Instance.GetForgeShopShopsAreMoreExpensiveRunModifierModifiedCost(cost);
			return GetCostWithMeissaDiscount(cost);
		}
		if (saiphGift)
		{
			cost = ReferenceSingleton<RunModifiersManager>.Instance.GetSentinelShopShopsAreMoreExpensiveRunModifierModifiedCost(cost);
			return GetCostWithSaiphDiscount(cost);
		}
		cost = ReferenceSingleton<RunModifiersManager>.Instance.GetEpicShopShopsAreMoreExpensiveRunModifierModifiedCost(cost);
		return cost;
	}

	protected int GetCostWithMeissaDiscount(int cost)
	{
		return Mathf.FloorToInt((float)cost * ReferenceSingleton<MiscOmensHandler>.Instance.GetMeissasDiscountAmount());
	}

	protected int GetCostWithSaiphDiscount(int cost)
	{
		return Mathf.FloorToInt((float)cost * ReferenceSingleton<MiscOmensHandler>.Instance.GetSaiphsDiscountAmount());
	}

	public virtual bool CheckCondition()
	{
		return true;
	}
}
